def multiplication_table(n):
    table = []
    for i in range(1, n + 1):
        row = []
        for j in range(1, n + 1):
            row.append(i * j)
        table.append(row)

    for k in range(n):
        for j in range(n):
            print(f"{table[k][j]:4}", end="")
        print()

    result = []
    for i in range(n):
        current_row = []
        for j in range(n):
            current_row.append(table[i][j])
        result.append(current_row)

    return result

