def are_anagrams(str1, str2):
    s1 = ""
    for c in str1:
        if 'a' <= c <= 'z' or 'A' <= c <= 'Z':
            s1 += c.lower()

    s2 = ""
    for d in str2:
        if 'a' <= d <= 'z' or 'A' <= d <= 'Z':
            s2 += d.lower()

    if len(s1) != len(s2):
        return False

    counts1 = {}
    for i in s1:
        counts1[i] = counts1.get(i, 0) + 1

    counts2 = {}
    for j in s2:
        counts2[j] = counts2.get(j, 0) + 1

    for k in counts1:
        if k not in counts2 or counts1[k] != counts2[k]:
            return False

    for n in counts2:
        if n not in counts1:
            return False

    return True

