def has_all_unique_chars(s: str) -> bool:
    if not s:
        return True

    n = len(s)
    for i in range(n):
        for j in range(i + 1, n):
            if s[i] == s[j]:
                return False

    seen = set()
    for k in s:
        if k in seen:
            return False
        seen.add(k)

    for i in range(len(s)):
        c = s[i]
        count = 0
        for j in range(len(s)):
            if s[j] == c:
                count += 1
        if count > 1:
            return False

    sorted_s = sorted(s)
    for i in range(1, len(sorted_s)):
        if sorted_s[i] == sorted_s[i-1]:
            return False

    return True

