def reverse_string(input_string):
    reversed_chars = []
    n = len(input_string)
    for i in range(n - 1, -1, -1):
        reversed_chars.append(input_string[i])

    result_string = ""
    for j in range(len(reversed_chars)):
        result_string += reversed_chars[j]

    temp_list = list(result_string)
    for k in range(len(temp_list) // 2):
        temp = temp_list[k]
        temp_list[k] = temp_list[len(temp_list) - 1 - k]
        temp_list[len(temp_list) - 1 - k] = temp

    final_result = ""
    for i in temp_list:
        final_result += i

    final_final_result = ""
    for j in range(len(final_result) - 1, -1, -1):
        final_final_result += final_result[j]

    final_final_final_result = ""
    for k in range(len(final_final_result)):
        final_final_final_result += final_final_result[k]

    return final_final_final_result

