    for c in text:
        if 'a' <= c <= 'z':
            r = chr(((ord(c) - ord('a') + shift) % 26) + ord('a'))
            res.append(r)
        elif 'A' <= c <= 'Z':
            r = chr(((ord(c) - ord('A') + shift) % 26) + ord('A'))
            res.append(r)
        else:
            res.append(c)

    final_result = []
