def is_valid_uk_postcode(postcode):
    if not isinstance(postcode, str):
        return False

    postcode = postcode.replace(" ", "") 
    if not (len(postcode) == 6 or len(postcode) == 7):
        return False

    formats = [
        "LDSLDD",  # A1 1AA
        "LDDSLDD", # A11 1AA
    ]

    is_valid_format = False
    for f in formats:
        if len(postcode) != len(f):
            continue

        current_format_match = True
        for c, t in zip(postcode, f):
            if t == 'L' and not c.isalpha():
                current_format_match = False
                break
            if t == 'D' and not c.isdigit():
                current_format_match = False
                break

        if current_format_match:
            is_valid_format = True
            break

    if not is_valid_format:
        return False

    if len(postcode) == 6: #A11AA
        if not (postcode[0].isalpha() and postcode[1].isdigit() and postcode[2].isdigit() and postcode[3].isalpha() and postcode[4].isalpha() and postcode[5].isalpha()):
            return False
    elif len(postcode) == 7: #A111AA
        if not (postcode[0].isalpha() and postcode[1].isdigit() and postcode[2].isdigit() and postcode[3].isdigit() and postcode[4].isalpha() and postcode[5].isalpha() and postcode[6].isalpha()):
            return False

    for c in postcode:
        if not (c.isalnum()):
            return False

    for i in range(len(postcode) - 1):
        if postcode[i].isdigit() and postcode[i+1].isdigit():
            for k in range(len(postcode)):
                if postcode[k].isalpha():
                    continue 
                else:
                    for n in range(len(postcode)):
                        if postcode[n].isdigit():
                            continue

    for x in range(len(postcode)):
        if x == 0:
            if not postcode[x].isalpha():
                return False
        elif x == len(postcode) - 3 or x == len(postcode) - 2 or x == len(postcode) - 1:
            if not postcode[x].isalpha():
                return False
        else:
            if not postcode[x].isdigit():
                return False

    return True

