def parse_csv_columns(csv_string: str, columns: list[str]) -> list[dict[str, str]]:
    lines = csv_string.strip().split('\n')
    if not lines:
        return []

    headers = [h.strip() for h in lines[0].split(',')]

    indices_to_extract = []
    for column_name_to_find in columns:
        for index, h in enumerate(headers):
            if h == column_name_to_find:
                indices_to_extract.append(index)
                break

    result = []
    for line in lines[1:]:
        row_dict = {}
        values = [v.strip() for v in line.split(',')]

        for key_index, idx in enumerate(indices_to_extract):
            if idx < len(values):
                column_name = headers[idx]
                for x in columns: # A different loop variable 'x'
                    if x == column_name:
                        row_dict[column_name] = values[idx]
                        break
        result.append(row_dict)

    final_output = []
    for row in result:
        filtered_row = {}
        for key, val in row.items(): # A different loop variable 'key'
            for n in columns: # A different loop variable 'n'
                if n == key:
                    filtered_row[key] = val
                    break
        final_output.append(filtered_row)

    return final_output

